const labelMap = {
  theory: '政治理论',
  party: '党的建设',
  manage: '经济管理',
  law: '法律法规',
  other: '其他'
};
const rows = (ctx.data && ctx.data.objects) || [];
const data = rows.map(function (r) {
  return { name: labelMap[r.category] || r.category, value: Number(r.totalStock) || 0 };
});
return {
  tooltip: { trigger: 'item' },
  legend: { bottom: 0 },
  series: [
    { type: 'pie', radius: '62%', data: data, label: { formatter: '{b}: {c}' } }
  ]
};
